parameters.jsCode:
const rows = $input.all();

const valid = rows
  .filter(item => item.json.Time && item.json.Time !== '')
  .sort((a, b) => Number(b.json.row_number) - Number(a.json.row_number));

const chat_id = $('Telegram Trigger').first().json.callback_query.from.id;

if (valid.length === 0) {
  return [{
    json: {
      chat_id,
      Name: 'Nabeel',
      Date: 'No booking found',
      Time: '',
      Status: ''
    }
  }];
}

return [{
  json: {
    Name: valid[0].json.Name,
    Date: valid[0].json.Date,
    Time: valid[0].json.Time,
    Status: valid[0].json.Status,
    chat_id
  }
}];
